import sys
sys.setrecursionlimit(10000)

def count_ways(n, memo):
    if n == 0:
        return 0
    if n == 1:
        return 1
    if n in memo:
        return memo.get(n - 1, 0)
    memo[n] = count_ways(n - 1, memo) + count_ways(n - 1, memo)
    return memo[n]

n = int(input())
print(count_ways(n, {}))
